/**
 * @fileoverview Test the usage of a private config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-config-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-private-config-usage', rule, {

    valid: [

    ],

    invalid: [
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                Ext.create('Ext.container.Viewport', {
                    layout: 'border',
                    allowDomMove: true,
                    items: [{
                        region: 'north',
                        html: '<h1 class="x-panel-header">Page Title</h1>',
                        border: false,
                        margin: '0 0 5 0'
                    }, {
                        region: 'west',
                        collapsible: true,
                        title: 'Navigation',
                        width: 150
                        // could use a TreePanel or AccordionLayout for navigational items
                    }, {
                        region: 'south',
                        title: 'South Panel',
                        collapsible: true,
                        html: 'Information goes here',
                        split: true,
                        height: 100,
                        minHeight: 100
                    }, {
                        region: 'east',
                        title: 'East Panel',
                        collapsible: true,
                        split: true,
                        width: 150
                    }, {
                        region: 'center',
                        xtype: 'tabpanel', // TabPanel itself has no title
                        activeTab: 0,      // First tab active by default
                        items: {
                            title: 'Default Tab',
                            html: 'The first tab content. Others may be added dynamically'
                        }
                    }]
                });
            `,
            errors: [{
                message: /Usage of private config 'allowDomMove' found for 'Ext.container.Viewport'/
            }]
        },
        {
            settings: {
                extjs: {
                    fromVersion: 4,
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('MyCustomApp.Application', {
                    name: 'MyCustomApp',
                    extend: 'Ext.app.Application',
                    //active: true
                });

                Ext.create({
                    xclass: 'Ext.app.Application',
                    name: 'MyCustomApp',
                    //active: true
                });

                var className = 'Ext.app.Application'
                Ext.create({
                    xclass: className,
                    name: 'MyCustomApp',
                    //active: true
                });

                Ext.define('MyApp.controller.Users', {
                    extend: 'Ext.app.Controller',
                    moduleClassName: 'Users'
                });
            `,
            errors: [
                // { message: /Usage of private config 'active' found for 'Ext.app.Application'/ },
                // { message: /Usage of private config 'active' found for 'Ext.app.Application'/ },
                // { message: /Usage of private config 'active' found for 'Ext.app.Application'/ },
                { message: /Usage of private config 'moduleClassName' found for 'Ext.app.Controller'/ }
            ]
        }
    ]
});
